async function authenticate(id){owner=id;const now=Math.floor(Date.now()/1000);const value=await encode({secret:'local-auth-disabled-fallback-secret',salt:'authjs.session-token',token:{id:String(id),sub:String(id),email:user(id).email,name:user(id).full_name,username:user(id).username,role:'user',accessToken:'p1-synthetic-access',refreshToken:'p1-synthetic-refresh',expiresIn:3600,userData:user(id),iat:now,exp:now+3600}});await context.addCookies([{name:'authjs.session-token',value,url:base,httpOnly:true,secure:false,sameSite:'Lax',expires:now+3600}]);}
async function screenshot(name,options={}){const duplicates=await page.locator('[id]').evaluateAll(nodes=>{const seen=new Set();return nodes.map(node=>node.id).filter(id=>seen.has(id)||!seen.add(id))});if(duplicates.length)checks.push({name:'unique DOM IDs at '+name,status:'FAIL',duplicates});await page.screenshot({path:path.join(output,name+'.png'),fullPage:true,...options});await writeFile(path.join(output,name+'.txt'),await page.locator('body').innerText());await writeFile(path.join(output,name+'-controls.json'),JSON.stringify(await page.locator('button').filter({visible:true}).evaluateAll(nodes=>nodes.map(node=>({text:node.innerText,label:node.getAttribute('aria-label'),title:node.getAttribute('title')}))),null,2));}
async function readyReview(panel){await panel.evaluate(async node=>{await document.fonts.ready;await Promise.all(node.getAnimations({subtree:true}).filter(animation=>animation.effect?.getTiming().iterations!==Infinity).map(animation=>animation.finished.catch(()=>{})));let previous='',stable=0;for(let frame=0;frame<120&&stable<3;frame++){await new Promise(requestAnimationFrame);const rect=node.getBoundingClientRect(),value=JSON.stringify([rect.x,rect.y,rect.width,rect.height,node.innerText]);stable=value===previous?stable+1:0;previous=value;}if(stable<3)throw Error('Review layout did not settle');});}
