 await record('Dashboard total info remains keyboard accessible with focus return',async()=>{await page.goto(base+'/console/dashboard');const trigger=page.getByRole('button',{name:'India total (portfolio + cash) info',exact:true});await trigger.waitFor();await trigger.focus();await page.keyboard.press('Enter');await page.getByRole('dialog').waitFor();await page.keyboard.press('Escape');await page.getByRole('dialog').waitFor({state:'hidden'});assert.equal(await trigger.evaluate(node=>node===document.activeElement),true);});
